<template>
  <div class="p-2">
    <Header v-if="isAuthenticated"></Header>
    <transition-group name="p-message" tag="div">
      <Message
          class="absolute right-0 mr-6"
          v-for="msg of messages"
          :key="msg.id"
          :severity="msg.severity"
      >
        {{ msg.message }}
      </Message>
    </transition-group>
    <router-view/>
  </div>
</template>
<script>
import Header from "@/components/shared/Header.vue";
import {mapActions, mapState} from "pinia";
import {userStore} from "@/store/user-calls";

export default {
  name: 'SoulSync',
  data: () => ({
    messages: []
  }),
  components: {
    Header
  },
  created() {
    this.emitter.on(
        'alert',
        alert => this.showAlert(alert)
    );
  },
  methods:{
    showAlert({severity,message}){
      this.messages.push({
        severity: severity,
        message: message,
        id: new Date().getMilliseconds()
      })
      setTimeout(() => this.messages.pop(),4000);
    },
    ...mapActions(userStore,['checkAuthenticated'])
  },
  computed: {
    ...mapState(userStore,['isAuthenticated'])
  }
}
</script>
<style>
.p-toolbar{
  border: none !important;
  border-radius: 1rem;
  padding: 1rem 1rem 1rem 1.5rem
}
</style>